<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { apiClient } from '@/services/api'
const route=useRoute(); const router=useRouter(); const id=route.params.id as string | undefined; const loading=ref(false); const error=ref(''); const success=ref(''); const form=ref({ email:'', password:'', employee_code:'', full_name:'', department:'', job_title:'', joining_date:'' })
async function load(){ if(!id)return; loading.value=true; try { const e=await apiClient.getEmployee(id); form.value={email:e.email,password:'',employee_code:e.employee_code,full_name:e.full_name,department:e.department||'',job_title:e.job_title||'',joining_date:e.joining_date} }catch(e){error.value=apiClient.getErrorMessage(e)}finally{loading.value=false} }
async function save(){ loading.value=true; error.value=''; success.value=''; try { if(id){ const {password,...data}=form.value; await apiClient.updateEmployee(id,data) } else { await apiClient.createEmployee(form.value) }; success.value='Saved successfully.'; setTimeout(()=>router.push('/employees'),500) }catch(e){error.value=apiClient.getErrorMessage(e)}finally{loading.value=false} }
onMounted(load)
</script>
<template><main class="mx-auto max-w-2xl space-y-6"><h1 class="text-2xl font-bold">{{ id ? 'Edit employee' : 'New employee' }}</h1><div v-if="error" class="rounded bg-red-50 p-3 text-red-700">{{ error }}</div><div v-if="success" class="rounded bg-green-50 p-3 text-green-700">{{ success }}</div><form class="space-y-4 rounded-lg bg-white p-6 shadow" @submit.prevent="save"><label class="block">Email<input v-model="form.email" required type="email" class="mt-1 w-full rounded border p-2" /></label><label v-if="!id" class="block">Password<input v-model="form.password" required type="password" class="mt-1 w-full rounded border p-2" /></label><label class="block">Employee code<input v-model="form.employee_code" required class="mt-1 w-full rounded border p-2" /></label><label class="block">Full name<input v-model="form.full_name" required class="mt-1 w-full rounded border p-2" /></label><div class="grid gap-4 sm:grid-cols-2"><label>Department<input v-model="form.department" class="mt-1 w-full rounded border p-2" /></label><label>Job title<input v-model="form.job_title" class="mt-1 w-full rounded border p-2" /></label></div><label class="block">Joining date<input v-model="form.joining_date" required type="date" class="mt-1 w-full rounded border p-2" /></label><div class="flex gap-3"><button class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-50" :disabled="loading">Save</button><button type="button" class="rounded border px-4 py-2" @click="router.back()">Cancel</button></div></form></main></template>
